[
    DataContractAttribute
]
final class METDutyAdValorumClaimGenerateContract extends METSysOperationTaskDataContract
{
    boolean   dutyValuesBySite;
    boolean   generateClaims;
    boolean   filterItemSite;
    str       vendClaimDutyRollVarTable;
    List      itemList = new List (Types::String);
    List      siteList = new List (Types::String);
    
}

